def merge_slots(slots: list[list[int]]) -> list[list[int]]:
    if not slots:
        return []
    # 開始時刻でソート
    slots.sort(key=lambda x: x[0])
    merged = [slots[0]]
    for cur in slots[1:]:
        prev = merged[-1]
        # 重なるかちょうど接する場合は統合
        if cur[0] <= prev[1]:
            prev[1] = max(prev[1], cur[1])
        else:
            merged.append(cur)
    return merged
```

