def stair_ways(n: int, broken: list[int]) -> int:
    MOD = 1000000007
    # mark broken steps
    is_broken = [False] * (n + 1)
    for b in broken:
        if 0 <= b <= n:
            is_broken[b] = True

    dp = [0] * (n + 1)
    dp[0] = 1  # start from step 0

    for i in range(1, n + 1):
        if is_broken[i]:
            dp[i] = 0
        else:
            ways = dp[i - 1]
            if i >= 2:
                ways += dp[i - 2]
            dp[i] = ways % MOD

    return dp[n] % MOD
