def rle_decode(s: str) -> str:
    i = 0
    n = len(s)
    out = []
    while i < n:
        if s[i].isdigit():
            j = i
            while j < n and s[j].isdigit():
                j += 1
            count = int(s[i:j])
            if j < n:
                out.append(s[j] * count)
                i = j + 1
            else:
                i = j
        else:
            out.append(s[i])
            i += 1
    return ''.join(out)
```

