def grid_islands(grid: list[str]) -> list[int]:
    if not grid:
        return []
    rows = len(grid)
    cols = len(grid[0])
    visited = [[False] * cols for _ in range(rows)]
    areas = []
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == '#' and not visited[r][c]:
                stack = [(r, c)]
                visited[r][c] = True
                size = 0
                while stack:
                    cr, cc = stack.pop()
                    size += 1
                    for dr, dc in dirs:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] == '#' and not visited[nr][nc]:
                                visited[nr][nc] = True
                                stack.append((nr, nc))
                areas.append(size)
    areas.sort(reverse=True)
    return areas
```

