def next_bus(times: list[str], now: str) -> str:
    """
    Returns the earliest bus departure time that is at or after `now`.
    If no such time exists today, returns the earliest time for the next day.
    """
    def to_min(t: str) -> int:
        h, m = map(int, t.split(":"))
        return h * 60 + m

    now_min = to_min(now)

    # Collect times that occur today (>= now)
    candidates = []
    for t in times:
        tm = to_min(t)
        if tm >= now_min:
            candidates.append((tm, t))

    if candidates:
        # Earliest among today's candidates
        return min(candidates)[1]
    else:
        # No candidate today; return the earliest time tomorrow
        return min(times, key=lambda t: to_min(t))
