def bracket_depth(s: str) -> int:
    opening = "({["
    closing = ")}]"
    match = {')': '(', ']': '[', '}': '{'}
    stack = []
    max_depth = 0
    for ch in s:
        if ch in opening:
            stack.append(ch)
            cur_depth = len(stack)
            if cur_depth > max_depth:
                max_depth = cur_depth
        elif ch in closing:
            if not stack:
                return -1
            top = stack.pop()
            if top != match[ch]:
                return -1
    if stack:
        return -1
    return max_depth
