def bracket_depth(s: str) -> int:
    opening = {'(', '[', '{'}
    closing = {')', ']', '}'}
    match = {')': '(', ']': '[', '}': '{'}

    stack = []
    current = 0
    max_depth = 0

    for ch in s:
        if ch in opening:
            stack.append(ch)
            current += 1
            if current > max_depth:
                max_depth = current
        elif ch in closing:
            if not stack:
                return -1
            top = stack.pop()
            if top != match[ch]:
                return -1
            current -= 1
        # ignore other characters

    if stack:
        return -1
    return max_depth
